  "casePrompt": "学校推行扁平化管理改革，取消年级组长岗位。改革初期教师反馈沟通效率提升；一段时间后出现责任推诿、决策混乱。校领导想退回传统层级制，但很多教师反对。请分析问题成因，并提出优化对策。",
  "caseSteps": [
    [
      "定方向",
      "用一句话说清学校要解决什么。",
      "保留沟通效率，同时恢复清晰的职责与决策秩序。"
    ],
    [
      "分析原因",
      "圈出题目动词和矛盾，从题干找证据，再提出可能原因。",
      "从责任推诿与决策混乱，追问谁负责、谁决策，以及问题如何升级。"
    ],
    [
      "明确目标",
      "写出改善后的具体表现。",
      "教师能快速找到负责人，跨部门问题有明确决策渠道。"
    ],
    [
      "提出措施",
      "每条写清动作，再补责任、流程或资源。",
      "明确年级事项负责人和授权边界，制定跨部门事项的协调与升级流程。"
    ],
    [
      "落实保障",
      "写清由谁牵头、在哪里试行、什么时候检查。",
      "由学校管理团队牵头，选择年级试行，定期收集教师反馈。"
    ],
    [
      "评价改进",
      "选能反映题干矛盾的证据，说明怎样调整。",
      "跟踪处理时长与责任争议，兼顾教师对沟通效率的反馈。"
    ],
    [
      "收束",
      "用一句话扣回题目的目标。",
      "在减少沟通层级的同时，把责任和决策流程落实到日常管理。"
    ]
  ],
